def subtract(a, b):
    # Filter out empty intervals and sort
    a_intervals = sorted([interval for interval in a if interval[0] < interval[1]])
    b_intervals = sorted([interval for interval in b if interval[0] < interval[1]])

    if not a_intervals:
        return []

    if not b_intervals:
        return a_intervals

    # Merge overlapping intervals in both a and b
    def merge_intervals(intervals):
        if not intervals:
            return []
        merged = [intervals[0]]
        for current in intervals[1:]:
            last = merged[-1]
            if current[0] <= last[1]:
                merged[-1] = [last[0], max(last[1], current[1])]
            else:
                merged.append(current)
        return merged

    a_merged = merge_intervals(a_intervals)
    b_merged = merge_intervals(b_intervals)

    result = []

    for a_start, a_end in a_merged:
        current_ranges = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            new_ranges = []
            for c_start, c_end in current_ranges:
                # No overlap
                if c_end <= b_start or c_start >= b_end:
                    new_ranges.append([c_start, c_end])
                else:
                    # There is overlap, keep the non-overlapping parts
                    if c_start < b_start:
                        new_ranges.append([c_start, b_start])
                    if c_end > b_end:
                        new_ranges.append([b_end, c_end])
            current_ranges = new_ranges

        result.extend(current_ranges)

    # Merge touching intervals in result
    result = sorted(result)
    if not result:
        return []

    merged_result = [result[0]]
    for current in result[1:]:
        last = merged_result[-1]
        if current[0] <= last[1]:
            merged_result[-1] = [last[0], max(last[1], current[1])]
        else:
            merged_result.append(current)

    return merged_result

